window.CH4={"missions": [{"id": "f1", "en": "Fossil or Fresh?", "zh": "化石还是近期物品", "art": "leaf-fossil", "page": "174–177", "tier": 1, "skill": "Observe & classify", "skillzh": "观察分类", "intro": "Read where each object came from. A familiar shape alone is not enough.", "introzh": "阅读物品的来源记录，仅凭熟悉的外形还不够。", "fact": "Fossils preserve remains or traces of past life. A leaf that fell yesterday is not already a fossil.", "factzh": "化石保存过去生命的遗存或痕迹。昨天落下的叶子还不是化石。", "share": "Why does the source record matter?", "sharezh": "来源记录为什么重要？", "artifact": "Fossil evidence tray", "artifactzh": "化石证据盘", "steps": [{"type": "sort", "en": "Use the records to sort the objects.", "zh": "根据来源记录分类。", "items": [{"id": "leaf", "en": "Ancient leaf print", "zh": "古代叶印", "art": "leaf-fossil", "clue": "Record: a leaf impression preserved in ancient rock.", "cluezh": "记录：古代岩石中保存着叶片印痕。", "to": "fossil"}, {"id": "bone", "en": "Ancient mineralized bone", "zh": "古代矿化骨", "art": "bone", "clue": "Record: an ancient bone preserved with minerals.", "cluezh": "记录：这块古代骨骼与矿物共同保存下来。", "to": "fossil"}, {"id": "fresh", "en": "Yesterday’s leaf", "zh": "昨天落下的叶子", "art": "leaf", "clue": "Record: this leaf fell yesterday.", "cluezh": "记录：这片叶子是昨天落下的。", "to": "recent"}], "groups": [{"id": "fossil", "en": "Fossil", "zh": "化石"}, {"id": "recent", "en": "Recent object", "zh": "近期物品"}], "hint": "Use age and preservation clues, not shape alone. 根据年代与保存线索，不只看形状。", "record": "PRESERVATION NOTE · 保存方式\nFossils can be preserved in rock, amber, ice, or natural asphalt.\n化石可以保存在岩石、琥珀、冰或天然沥青中。", "recordAudio": "Fossils can be preserved in rock, amber, ice, or natural asphalt."}, {"type": "choice", "en": "Can a leaf-shaped drawing prove that an object is a fossil?", "zh": "叶子形状的图案能单独证明物品是化石吗？", "options": ["Yes, any leaf shape is a fossil.", "No. We need its source and preservation record."], "answer": 1, "hint": "An object’s history matters. 物品的历史很重要。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["The ancient leaf print", "is a fossil.", "Yesterday’s leaf is not."], "translation": "古代叶印是化石，昨天的落叶不是。", "hint": "The ancient leaf print is a fossil. Yesterday’s leaf is not."}]}, {"id": "f2", "en": "Traces of Life", "zh": "生命留下的痕迹", "art": "tracks", "page": "176–177", "tier": 1, "skill": "Observe & classify", "skillzh": "观察分类", "intro": "Compare a preserved body part with a preserved sign of movement.", "introzh": "比较保存下来的身体部分与活动痕迹。", "fact": "An ancient preserved footprint is a trace fossil. It records activity rather than a body part.", "factzh": "古代保存下来的足迹属于遗迹化石，记录的是活动而不是身体部分。", "share": "What can a track show that a tooth cannot?", "sharezh": "脚印能展示哪些牙齿不能展示的线索？", "artifact": "Body and trace display", "artifactzh": "实体与遗迹展板", "steps": [{"type": "sort", "en": "Match each fossil to the kind of evidence.", "zh": "把化石与证据类型对应。", "items": [{"id": "tooth", "en": "Preserved tooth", "zh": "保存的牙齿", "art": "tooth", "clue": "This is a preserved part of an animal’s body.", "cluezh": "这是保存下来的动物身体部分。", "to": "body"}, {"id": "bone", "en": "Preserved bone", "zh": "保存的骨骼", "art": "bone", "clue": "This is a preserved body part.", "cluezh": "这是保存下来的身体部分。", "to": "body"}, {"id": "track", "en": "Ancient trackway", "zh": "古代足迹串", "art": "tracks", "clue": "These prints record an animal moving across mud.", "cluezh": "这串印痕记录了动物穿过泥地的活动。", "to": "trace"}], "groups": [{"id": "body", "en": "Body remains", "zh": "身体遗存"}, {"id": "trace", "en": "Activity trace", "zh": "活动痕迹"}], "hint": "A footprint is not the animal’s foot. 脚印不是动物的脚本身。"}, {"type": "choice", "en": "Could a footprint preserved from long ago be a fossil?", "zh": "很久以前保存下来的足迹可以是化石吗？", "options": ["Yes, a trace fossil.", "No, only bones are fossils."], "answer": 0, "hint": "Fossils include traces as well as remains. 化石包括痕迹和遗存。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["An ancient preserved footprint", "can be a fossil", "of an animal’s activity."], "translation": "古代保存下来的足迹可以是动物活动的遗迹化石。", "hint": "An ancient preserved footprint can be a fossil of an animal’s activity."}]}, {"id": "f3", "en": "Make a Model Print", "zh": "制作印痕模型", "art": "shell", "page": "174–181", "tier": 1, "skill": "Observe & classify", "skillzh": "观察分类", "intro": "Press a shell into soft clay, then lift it away. Watch what stays behind.", "introzh": "把贝壳压入软泥，再拿开，观察留下的形状。", "fact": "This is a model impression, not an ancient fossil. A shell impression shows body shape. A footprint records activity.", "factzh": "这是印痕模型，不是古代化石。贝壳印痕展示身体形状；足迹记录活动。", "share": "Which parts of real fossil formation does this model leave out?", "sharezh": "模型省略了真实化石形成的哪些过程？", "artifact": "My shell impression", "artifactzh": "我的贝壳印痕", "steps": [{"type": "imprint", "en": "Press, lift, and inspect the impression.", "zh": "按压、拿开，再观察印痕。", "items": [{"id": "press"}, {"id": "lift"}], "hint": "Press the shell first, then lift it. 先按压贝壳，再拿开。"}, {"type": "choice", "en": "What have you made?", "zh": "你刚才做出了什么？", "options": ["An ancient fossil formed in seconds.", "A model print in soft clay."], "answer": 1, "hint": "The model shows shape transfer, not ancient time. 模型展示形状留下印痕，不代表古老时间。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["I made a model print.", "It shows a shell’s shape,", "not a real ancient fossil."], "translation": "我制作了印痕模型，展示贝壳形状，不是真正古老的化石。", "hint": "I made a model print. It shows a shell’s shape, not a real ancient fossil."}]}, {"id": "f4", "en": "A Long Story in Layers", "zh": "层层埋藏的故事", "art": "burial", "page": "178–181", "tier": 2, "skill": "Test & explain", "skillzh": "测试解释", "intro": "Arrange one possible path from a buried shell to a fossil discovery.", "introzh": "排列从贝壳埋藏到发现化石的一种可能过程。", "fact": "Burial can protect remains. Fossil preservation takes suitable conditions; not everything buried becomes a fossil.", "factzh": "埋藏可以保护遗存。化石保存需要适宜条件，不是所有埋藏的生物都会变成化石。", "share": "Why might some buried remains disappear?", "sharezh": "为什么有些埋藏遗存会消失？", "artifact": "Preservation timeline", "artifactzh": "保存过程时间线", "steps": [{"type": "order", "en": "Put this simplified story in order.", "zh": "排列这个简化故事。", "items": [{"id": "bury", "en": "Buried shell", "zh": "贝壳被埋藏", "art": "burial", "clue": "Sediment covers a shell.", "cluezh": "沉积物覆盖了贝壳。", "to": null}, {"id": "layers", "en": "More sediment", "zh": "更多沉积物", "art": "layers", "clue": "More layers build up above it.", "cluezh": "更多沉积层在上方堆积。", "to": null}, {"id": "preserve", "en": "Preserved over time", "zh": "随时间保存", "art": "shell-fossil", "clue": "Under suitable conditions, a fossil is preserved.", "cluezh": "适宜条件下，化石得到保存。", "to": null}, {"id": "find", "en": "Later discovery", "zh": "后来被发现", "art": "brush", "clue": "Much later, the fossil is discovered.", "cluezh": "很久以后，这块化石被发现。", "to": null}], "hint": "Burial → more layers → preservation → discovery. 埋藏→覆盖→保存→发现。"}, {"type": "choice", "en": "Does every buried shell become a fossil?", "zh": "每个被埋藏的贝壳都会变成化石吗？", "options": ["No. Suitable preservation conditions are needed.", "Yes, always."], "answer": 0, "hint": "This is one possible pathway. 这只是一种可能过程。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["Some buried remains", "can be preserved as fossils", "under suitable conditions."], "translation": "有些被埋藏的遗存在适宜条件下能保存为化石。", "hint": "Some buried remains can be preserved as fossils under suitable conditions."}]}, {"id": "f5", "en": "Earlier and Later", "zh": "先后顺序的线索", "art": "layers", "page": "178–181", "tier": 2, "skill": "Test & explain", "skillzh": "测试解释", "intro": "Read an undisturbed layer model. Compare order without inventing exact dates.", "introzh": "阅读未扰动的地层模型，比较先后，不编造精确年代。", "fact": "In this undisturbed model, lower layers formed earlier. Relative order does not give an exact age in years.", "factzh": "在这个未扰动模型中，下层形成得较早。相对先后不能给出精确年份。", "share": "What would change if the layers had been overturned?", "sharezh": "如果地层翻转了，判断需要怎样改变？", "artifact": "Layer sequence chart", "artifactzh": "地层先后图", "steps": [{"type": "order", "en": "Order these layers from earlier to later.", "zh": "把地层按形成时间从早到晚排列。", "items": [{"id": "C", "en": "Layer C · bottom", "zh": "底层C", "art": "layer-c", "clue": "Bottom layer in an undisturbed model.", "cluezh": "未扰动地层模型中的底层。", "to": null}, {"id": "B", "en": "Layer B · middle", "zh": "中层B", "art": "layer-b", "clue": "Middle layer in an undisturbed model.", "cluezh": "未扰动地层模型中的中层。", "to": null}, {"id": "A", "en": "Layer A · top", "zh": "顶层A", "art": "layer-a", "clue": "Top layer in an undisturbed model.", "cluezh": "未扰动地层模型中的顶层。", "to": null}], "hint": "In this model: bottom, middle, top. 本模型：底层、中层、顶层。", "recall": "Revisit the clues · 从观察走向有依据的解释", "record": "LAYER MODEL · 地层模型\nNot overturned or disturbed / 未翻转、未扰动\nTOP: A — leaf fossil / 顶层A：叶化石\nMIDDLE: B — shell fossil / 中层B：贝壳化石\nBOTTOM: C — fish fossil / 底层C：鱼化石", "recordAudio": "This layer model has not been overturned or disturbed. Layer A is at the top and has a leaf fossil. Layer B is in the middle and has a shell fossil. Layer C is at the bottom and has a fish fossil."}, {"type": "choice", "en": "Can this diagram alone tell us an exact age in years?", "zh": "仅靠这幅图能得知精确年龄吗？", "options": ["Yes, the bottom layer is exactly one million years old.", "No. It shows relative order, not an exact date."], "answer": 1, "hint": "Earlier is not the same as an exact number of years. 较早不等于精确年数。", "record": "LAYER MODEL · 地层模型\nNot overturned or disturbed / 未翻转、未扰动\nTOP: A — leaf fossil / 顶层A：叶化石\nMIDDLE: B — shell fossil / 中层B：贝壳化石\nBOTTOM: C — fish fossil / 底层C：鱼化石", "recordAudio": "This layer model has not been overturned or disturbed. Layer A is at the top and has a leaf fossil. Layer B is in the middle and has a shell fossil. Layer C is at the bottom and has a fish fossil."}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["In this undisturbed model,", "layer C formed before layer A.", "We do not know their exact ages."], "translation": "在这个未扰动模型中，C层早于A层；我们不知道它们的精确年代。", "hint": "In this undisturbed model, layer C formed before layer A. We do not know their exact ages."}]}, {"id": "f6", "en": "A Fish in a Dry Place", "zh": "干燥地方的鱼化石", "art": "fish-fossil", "page": "184–187", "tier": 2, "skill": "Test & explain", "skillzh": "测试解释", "intro": "Open the field records. Use the fossil and its original rock layer together.", "introzh": "打开考察记录，结合化石与原位岩层判断。", "fact": "A fish fossil in its original sedimentary layer can support the idea that water was once present there.", "factzh": "原位沉积层中的鱼化石，可以支持这里曾有水的推测。", "share": "Why is an original rock layer better evidence than a souvenir on the ground?", "sharezh": "为什么原位岩层比地上的纪念品更有证据价值？", "artifact": "Ancient water evidence", "artifactzh": "古水环境证据", "steps": [{"type": "survey", "en": "Inspect all three field records.", "zh": "调查三份野外记录。", "items": [{"id": "place", "en": "Place today", "zh": "现在的地点", "art": "desert", "clue": "Today this site is dry.", "cluezh": "这个地点现在很干燥。"}, {"id": "find", "en": "Fossil", "zh": "化石", "art": "fish-fossil", "clue": "A fish fossil was found here.", "cluezh": "这里发现鱼化石。"}, {"id": "layer", "en": "Layer record", "zh": "岩层记录", "art": "layers", "clue": "The fossil was embedded in its original sedimentary layer, not brought here by a visitor.", "cluezh": "化石嵌在原位沉积层中，不是游客带来的。"}], "hint": "Inspect place, fossil, and layer records. 查看地点、化石和岩层记录。", "recall": "Revisit the clues · 从观察走向有依据的解释"}, {"type": "choice", "en": "Which explanation fits these records?", "zh": "哪个解释符合记录？", "options": ["Water may have covered this place in the past.", "The fish lived without water.", "This place has always been dry."], "answer": 0, "hint": "Use the original-layer record and the fish together. 结合原位岩层与鱼的证据。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["This fish fossil", "suggests that water", "may have been here long ago."], "translation": "这块鱼化石提示，这里很久以前可能有水。", "hint": "This fish fossil suggests that water may have been here long ago."}]}, {"id": "f7", "en": "Fit the Skeleton", "zh": "拼出骨骼模型", "art": "skeleton", "page": "188–191", "tier": 3, "skill": "Compare evidence", "skillzh": "比较证据", "intro": "Use the labeled reference to assemble a simplified skeleton. Leave unsupported details unknown.", "introzh": "按参照图把骨骼与身体区域对应，没有证据的细节保持未知。", "fact": "Bones provide evidence about body structure. These bones alone do not reveal exact skin color.", "factzh": "骨骼提供身体结构证据，仅靠这些骨骼不能确定准确皮肤颜色。", "share": "Which extra evidence might help us learn more?", "sharezh": "什么额外证据能帮助了解更多？", "artifact": "Skeleton evidence board", "artifactzh": "骨架证据板", "steps": [{"type": "sort", "en": "Match each piece to the labeled reference region.", "zh": "把骨骼部分放入参照图对应区域。", "items": [{"id": "skull", "en": "Skull", "zh": "头骨", "art": "skull", "clue": "Reference: the skull belongs at the head.", "cluezh": "参照图：头骨位于头部。", "to": "head"}, {"id": "ribs", "en": "Rib cage", "zh": "胸廓", "art": "ribs", "clue": "Reference: ribs surround the chest.", "cluezh": "参照图：肋骨围绕胸部。", "to": "chest"}, {"id": "leg", "en": "Leg bones", "zh": "腿骨", "art": "leg", "clue": "Reference: leg bones extend below the body.", "cluezh": "参照图：腿骨从躯干下方向下延伸。", "to": "limbs"}], "groups": [{"id": "head", "en": "Head region", "zh": "头部"}, {"id": "chest", "en": "Chest region", "zh": "胸部"}, {"id": "limbs", "en": "Limb region", "zh": "肢体"}], "hint": "Use the reference regions; this is a simplified model. 使用参照区域，这是简化模型。", "recall": "Revisit the clues · 从观察走向有依据的解释", "illustration": "skeleton"}, {"type": "choice", "en": "Can these bones alone tell us the exact skin color?", "zh": "仅靠这些骨骼能知道准确皮肤颜色吗？", "options": ["Yes, choose any color.", "No. Mark the color as unknown."], "answer": 1, "hint": "Do not fill an evidence gap with a guess. 不用猜测填补证据空白。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["The bones show", "body structure.", "These bones alone do not show skin color."], "translation": "骨骼显示身体结构，仅靠这些骨骼不能知道皮肤颜色。", "hint": "The bones show body structure. These bones alone do not show skin color."}]}, {"id": "f8", "en": "Living or Extinct?", "zh": "现生还是灭绝", "art": "mammoth", "page": "188–189", "tier": 3, "skill": "Compare evidence", "skillzh": "比较证据", "intro": "Read species records. One dead animal and an extinct species are different ideas.", "introzh": "阅读物种记录，一只动物死亡与一个物种灭绝不是同一概念。", "fact": "Extinct means that no living members of a species remain anywhere on Earth.", "factzh": "灭绝指一个物种在地球任何地方都已没有存活个体。", "share": "Could one elephant die while its species remains alive?", "sharezh": "一只象死亡时，它的物种还能继续存在吗？", "artifact": "Species status cards", "artifactzh": "物种状态卡", "steps": [{"type": "sort", "en": "Use the records to classify these species.", "zh": "根据记录判断物种状态。", "items": [{"id": "mammoth", "en": "Columbian mammoth", "zh": "哥伦比亚猛犸象", "art": "mammoth", "clue": "Record: no living members of this species remain.", "cluezh": "物种记录：地球上已无该物种的存活个体。", "to": "extinct"}, {"id": "elephant", "en": "Asian elephant", "zh": "亚洲象", "art": "elephant", "clue": "Record: living members of this species exist today.", "cluezh": "物种记录：如今仍有该物种的存活个体。", "to": "living"}], "groups": [{"id": "living", "en": "Living species", "zh": "现生物种"}, {"id": "extinct", "en": "Extinct species", "zh": "已灭绝物种"}], "hint": "Look for living members of the whole species. 看整个物种是否还有存活个体。"}, {"type": "choice", "en": "One animal dies. Does that alone mean its species is extinct?", "zh": "一只动物死亡就代表物种灭绝吗？", "options": ["No. Other members may still be alive.", "Yes, always."], "answer": 0, "hint": "Individual and species are different levels. 个体和物种是不同层次。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["An extinct species", "has no living members", "anywhere on Earth."], "translation": "已灭绝物种在地球任何地方都没有存活个体。", "hint": "An extinct species has no living members anywhere on Earth."}]}, {"id": "f9", "en": "A California Field Trip", "zh": "加州化石考察", "art": "asphalt", "page": "192–197", "tier": 3, "skill": "Compare evidence", "skillzh": "比较证据", "intro": "Visit a virtual La Brea collection. Compare large and tiny fossils.", "introzh": "参观虚拟拉布雷亚藏品，比较大型与微小化石。", "fact": "La Brea in Los Angeles preserves fossils in natural asphalt, including mammoths and small plant and animal remains.", "factzh": "洛杉矶拉布雷亚的天然沥青保存了猛犸象以及小型动植物遗存等化石。", "share": "Why should a museum keep tiny seeds as well as large bones?", "sharezh": "博物馆为什么也要保存小种子，不只保存大骨骼？", "artifact": "La Brea field notebook", "artifactzh": "拉布雷亚考察笔记", "steps": [{"type": "survey", "en": "Open the three collection records.", "zh": "打开三份藏品记录。", "items": [{"id": "site", "en": "La Brea", "zh": "拉布雷亚", "art": "asphalt", "clue": "Los Angeles, California, USA. Natural asphalt preserved many remains.", "cluezh": "美国加州洛杉矶，天然沥青保存许多遗存。"}, {"id": "mammoth", "en": "Mammoth", "zh": "猛犸象", "art": "mammoth", "clue": "The Columbian mammoth was a mammal, not a dinosaur.", "cluezh": "哥伦比亚猛犸象是哺乳动物，不是恐龙。"}, {"id": "seed", "en": "Tiny remains", "zh": "微小遗存", "art": "seed", "clue": "Small plant and animal fossils also give clues about ancient life.", "cluezh": "微小动植物化石也提供古代生命线索。"}], "hint": "Read all three collection records. 阅读三份藏品记录。", "recall": "Revisit the clues · 从观察走向有依据的解释", "record": "ANOTHER CALIFORNIA EXAMPLE · 另一种加州化石\nPetrified wood preserves wood structure as minerals fill or replace the original material.\n硅化木的原有材料被矿物填充或替代，木材结构得到保存。", "recordAudio": "Another California example is petrified wood. Minerals fill or replace the original material while preserving wood structure."}, {"type": "choice", "en": "Which classification fits the mammoth?", "zh": "猛犸象属于哪一类？", "options": ["Dinosaur", "Mammal", "Fish"], "answer": 1, "hint": "Connect with Animal Cove: mammoths belonged to the mammal group. 联系动物海湾：猛犸象属于哺乳动物。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["Large bones and tiny remains", "both give clues", "about life in the past."], "translation": "大型骨骼和微小遗存都提供过去生命的线索。", "hint": "Large bones and tiny remains both give clues about life in the past."}]}, {"id": "f10", "en": "Plants Beneath the Ice", "zh": "冰层下的植物线索", "art": "palm-fossil", "page": "186–187", "tier": 4, "skill": "Transfer & defend", "skillzh": "迁移论证", "intro": "Compare an ancient plant fossil with a modern plant record. Keep the conclusion cautious.", "introzh": "比较古代植物化石和现生植物记录，谨慎作出结论。", "fact": "Plant fossils can help scientists infer past environments when combined with comparisons and geological context.", "factzh": "结合比较和地质背景，植物化石可以帮助科学家推测过去环境。", "share": "Does a plant fossil tell us the exact temperature on one day?", "sharezh": "植物化石能告诉我们某天的精确气温吗？", "artifact": "Past climate explanation", "artifactzh": "古环境解释卡", "steps": [{"type": "choice", "en": "What idea do these records support?", "zh": "这些记录支持哪个推测？", "options": ["This place may have been warmer in the past.", "It was exactly 25 degrees every day.", "The plant grew on modern ice."], "answer": 0, "hint": "Use “may” and avoid inventing exact numbers. 使用“可能”，不编造精确数字。", "record": "FIELD MODEL · 考察模型\nAn ancient palm-like fossil is found in its original layer in Antarctica.\n在南极原位岩层中发现古代棕榈状植物化石。\nComparison record: related plants grow in warmer places today.\n比较记录：相关植物如今生长在较温暖地区。", "recall": "Revisit the clues · 从观察走向有依据的解释", "recordAudio": "In this field model, an ancient palm-like fossil is in its original layer in Antarctica. Related plants grow in warmer places today."}, {"type": "multi", "en": "Choose two useful kinds of evidence.", "zh": "选择两种有用证据。", "options": ["The fossil’s original layer", "A guessed flower color", "Comparison with related living plants"], "answers": [0, 2], "min": 2, "hint": "Combine fossil context with living comparisons. 结合化石背景与现生比较。"}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["This plant fossil", "and the comparison record", "suggest a warmer past environment."], "translation": "这块植物化石与比较记录提示过去环境较温暖。", "hint": "This plant fossil and the comparison record suggest a warmer past environment."}]}, {"id": "f11", "en": "Evidence, Idea, Unknown", "zh": "证据、推断与未知", "art": "label", "page": "184–191", "tier": 4, "skill": "Transfer & defend", "skillzh": "迁移论证", "intro": "Sort a museum team’s notes. Distinguish observations from interpretations and missing information.", "introzh": "整理博物馆笔记，区分观察、解释与缺失信息。", "fact": "A careful museum label separates what is observed, what is inferred, and what the evidence cannot tell us.", "factzh": "谨慎的展签区分观察到的内容、推断，以及证据无法回答的问题。", "share": "Can “unknown” be a good scientific answer?", "sharezh": "“未知”可以是好的科学回答吗？", "artifact": "Three-part museum label", "artifactzh": "三栏科学展签", "steps": [{"type": "sort", "en": "Place each note under the right heading.", "zh": "把笔记放到对应标题下。", "items": [{"id": "evidence", "en": "Fish bones in the original layer", "zh": "原位岩层中有鱼骨", "art": "fish-fossil", "clue": "This is the recorded observation.", "cluezh": "这是实际记录到的观察结果。", "to": "evidence"}, {"id": "idea", "en": "Water may once have been here", "zh": "这里过去可能有水", "art": "water", "clue": "This is an interpretation supported by the fossil context.", "cluezh": "这是结合化石背景作出的有依据的解释。", "to": "idea"}, {"id": "unknown", "en": "The fish’s exact skin color", "zh": "鱼的准确皮肤颜色", "art": "unknown", "clue": "The record has no preserved color evidence.", "cluezh": "记录中没有保存下来的颜色证据。", "to": "unknown"}], "groups": [{"id": "evidence", "en": "Evidence", "zh": "证据"}, {"id": "idea", "en": "Supported idea", "zh": "有依据的推断"}, {"id": "unknown", "en": "Unknown", "zh": "未知"}], "hint": "Observed bone, possible water, unknown color. 观察到骨骼；推测有水；颜色未知。", "recall": "Revisit the clues · 从观察走向有依据的解释"}, {"type": "choice", "en": "Which museum sentence is too strong?", "zh": "哪句话超出了证据？", "options": ["The fossil includes fish bones.", "Water may once have covered this place.", "This fish was definitely bright blue."], "answer": 2, "hint": "The record contains no color evidence. 记录中没有颜色证据。", "record": ""}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["I can see fossil bones.", "They support an idea about past water.", "They do not tell me the exact color."], "translation": "我能看到化石骨骼。它们支持过去有水的推测，但不能告诉我准确颜色。", "hint": "I can see fossil bones. They support an idea about past water. They do not tell me the exact color."}]}, {"id": "f12", "en": "Open the Fossil Museum", "zh": "开放化石博物馆", "art": "museum", "page": "206–209", "tier": 4, "skill": "Transfer & defend", "skillzh": "迁移论证", "intro": "Check the final exhibition. Use the same reasoning with a new shell fossil.", "introzh": "检查最终展览，用同样的推理方法处理新的贝壳化石。", "fact": "Good fossil explanations use source records, comparisons, and clear limits on what is known.", "factzh": "好的化石解释使用来源记录、比较与清楚的知识边界。", "share": "Which exhibit would you explain to a visitor first?", "sharezh": "你会先向参观者解释哪个展品？", "artifact": "Fossil Canyon exhibition", "artifactzh": "化石峡谷研究展", "steps": [{"type": "choice", "en": "Which label fits this new shell fossil?", "zh": "哪张展签符合新的贝壳化石？", "options": ["Water may have been here when this layer formed.", "This was definitely an ocean exactly one million years ago.", "All shells live on dry land."], "answer": 0, "hint": "Water is supported; exact age and ocean type are not given. 支持有水，未给精确年代与海洋类型。", "record": "NEW RECORD · 新记录\nAn aquatic shell fossil is embedded in its original sedimentary layer.\n原位沉积层中保存着水生贝类化石。\nNo exact age or salt-water/fresh-water evidence is provided.\n没有提供精确年代或咸淡水证据。", "recall": "Revisit the clues · 从观察走向有依据的解释", "recordAudio": "A fossil shell from a water animal is in its original sedimentary layer. We have no exact age, and no evidence to choose between fresh water and salt water."}, {"type": "sort", "en": "Check the exhibition labels.", "zh": "审核展览标签。", "items": [{"id": "model", "en": "Our clay print is a model", "zh": "软泥印痕是模型", "art": "shell", "clue": "A model made today is not an ancient fossil.", "cluezh": "今天制作的模型不是古代化石。", "to": "keep"}, {"id": "extinct", "en": "Extinct means one animal died", "zh": "灭绝就是一只动物死亡", "art": "mammoth", "clue": "Extinction refers to the whole species.", "cluezh": "灭绝针对整个物种，而非单个个体。", "to": "fix"}, {"id": "layers", "en": "Lower is earlier in this undisturbed model", "zh": "未扰动模型中下层较早", "art": "layers", "clue": "The stated model has not been overturned.", "cluezh": "这个指定模型中的地层没有翻转。", "to": "keep"}], "groups": [{"id": "keep", "en": "Keep this label", "zh": "保留展签"}, {"id": "fix", "en": "Revise this label", "zh": "修正展签"}], "hint": "Check the model, species meaning, and layer condition. 检查模型、物种含义和地层条件。"}, {"type": "sentence", "en": "Build your explanation.", "zh": "拼出你的解释。", "parts": ["This fossil is evidence of past life.", "I use its source record", "to explain what it may mean.", "Some details remain unknown."], "translation": "化石是过去生命的证据。我用来源记录解释可能含义，有些细节仍然未知。", "hint": "This fossil is evidence of past life. I use its source record to explain what it may mean. Some details remain unknown."}]}], "tiers": [{"en": "Find past life", "zh": "寻找过去生命", "range": "01–03"}, {"en": "Read time & place", "zh": "解读时间与环境", "range": "04–06"}, {"en": "Compare the clues", "zh": "比较多种线索", "range": "07–09"}, {"en": "Build an explanation", "zh": "构建有依据的解释", "range": "10–12"}]};
window.CH4.audio={};window.CH4.missions.forEach(m=>{window.CH4.audio[m.id+'-intro']=m.intro;window.CH4.audio[m.id+'-fact']=m.fact;m.steps.forEach((s,i)=>{window.CH4.audio[m.id+'-step'+i]=s.en+(s.options?' '+(s.type==='multi'?'Choose '+s.min+' statements. ':'Choose one answer. ')+s.options.map((o,j)=>String.fromCharCode(65+j)+'. '+o).join(' '):'');if(s.type==='sentence')window.CH4.audio[m.id+'-sentence']=s.parts.join(' ');if(s.recordAudio)window.CH4.audio[m.id+'-record'+i]=s.recordAudio;(s.items||[]).filter(it=>it.clue).forEach(it=>window.CH4.audio[m.id+'-clue'+i+'-'+it.id]=it.en+'. '+it.clue);});});
window.validateFossils=function(a){
 if(a===undefined)return {completed:[],drafts:{},works:{},shared:[]};
 const bad=()=>{throw Error('第四章存档内容无效')};
 if(!a||!Array.isArray(a.completed)||a.completed.length>12||a.completed.some((v,i)=>v!==i)||!a.drafts||typeof a.drafts!=='object'||Array.isArray(a.drafts)||!a.works||typeof a.works!=='object'||Array.isArray(a.works))bad();
 const validStep=(x,s)=>{
  if(!x||typeof x!=='object'||Array.isArray(x))bad();
  const ids=s.items?.map(t=>t.id)||[];
  for(const key of Object.keys(x))if(!['seen','placed','order','selected','prediction','views','bg','hint','checked','tokens','opened'].includes(key))bad();
  for(const key of ['seen','order','opened'])if(x[key]!==undefined&&(!Array.isArray(x[key])||x[key].length>12||x[key].some(v=>!ids.includes(v))||new Set(x[key]).size!==x[key].length))bad();
  if(x.placed!==undefined){if(!x.placed||typeof x.placed!=='object'||Array.isArray(x.placed))bad();for(const [id,g] of Object.entries(x.placed))if(!ids.includes(id)||!s.groups?.some(t=>t.id===g))bad();}
  if(x.selected!==undefined&&(!Array.isArray(x.selected)||new Set(x.selected).size!==x.selected.length||x.selected.some(v=>!Number.isInteger(v)||v<0||v>=(s.type==='population'?8:s.options?.length||0))))bad();
  if(x.tokens!==undefined&&(!Array.isArray(x.tokens)||new Set(x.tokens).size!==x.tokens.length||x.tokens.some(v=>!Number.isInteger(v)||v<0||v>=(s.parts?.length||0))))bad();
  if(x.prediction!==undefined&&!['green','brown','unsure'].includes(x.prediction))bad();
  if(x.bg!==undefined&&!['green','brown'].includes(x.bg))bad();
  if(x.views!==undefined&&(!Array.isArray(x.views)||x.views.length>2||x.views.some(v=>!['green','brown'].includes(v))))bad();
  for(const k of ['hint','checked'])if(x[k]!==undefined&&typeof x[k]!=='boolean')bad();
 };
 for(const collection of ['drafts','works'])for(const [id,d] of Object.entries(a[collection])){
  const m=window.CH4.missions.find(m=>m.id===id);if(!m||!d||!Number.isInteger(d.step)||d.step<0||d.step>=m.steps.length||!d.answers||typeof d.answers!=='object'||Array.isArray(d.answers))bad();
  for(const [idx,x] of Object.entries(d.answers)){if(!/^\d+$/.test(idx)||!m.steps[+idx])bad();validStep(x,m.steps[+idx]);}
 }
 if(a.shared!==undefined&&(!Array.isArray(a.shared)||a.shared.some(x=>!Number.isInteger(x)||!a.completed.includes(x))||new Set(a.shared).size!==a.shared.length))bad();
 return {completed:[...a.completed],drafts:a.drafts,works:a.works,shared:a.shared||[]};
};
